import { Mesh, PlaneGeometry, Group } from 'three/webgpu';
import {
  MeshStandardNodeMaterial,
  uniform,
  color,
  mix,
  smoothstep,
  uv,
  vec3,
  mul,
  add,
} from 'three/tsl';
import { gsap } from 'gsap';
import {} from '@/primitives';
import {} from '@/text';

export default function createNode(config, ctx) {
  const { Group: ThreeGroup } = ctx.THREE;

  // Root group
  const root = new ThreeGroup();

  // Dimensions
  const width = 2.6;
  const height = 0.68;
  const bevelDepth = 0.03;
  const cornerRadius = 0.08;

  // Geometry for the button plane (flat, no bevel geometry, but we will simulate bevel via lighting)
  const buttonGeom = new PlaneGeometry(width, height);
  buttonGeom.computeVertexNormals();

  // Gradient colors
  const gradColor1 = color('#ff4450');
  const gradColor2 = color('#ff2a38');
  const gradColor3 = color('#c1121f');

  // Uniform for edge emissive intensity (hover animation)
  const edgeIntensity = uniform(1.6);

  // UV Y coordinate
  const uvY = uv().y;

  // Vertical gradient node
  const gradientNode = mix(
    mix(gradColor1, gradColor2, smoothstep(0.0, 0.55, uvY)),
    gradColor3,
    smoothstep(0.55, 1.0, uvY)
  );

  // Emissive node for the edge band (constant accent color multiplied by intensity)
  const edgeEmissiveNode = mul(color('#ff2a38'), edgeIntensity);

  // Base button material (PBR)
  const buttonMat = new MeshStandardNodeMaterial();
  buttonMat.colorNode = gradientNode;
  buttonMat.roughness = 0.5;
  buttonMat.metalness = 0.35;
  buttonMat.clearcoat = 0.22;
  buttonMat.emissiveNode = edgeEmissiveNode; // perimeter emissive (simulated across whole surface)

  // Button mesh
  const buttonMesh = new Mesh(buttonGeom, buttonMat);
  // Align plane to face camera (+Z forward)
  buttonMesh.rotation.x = -Math.PI / 2;
  root.add(buttonMesh);

  // Contact shadow plane (0.08 below button)
  const shadowGeom = new PlaneGeometry(width, height);
  const shadowMat = new MeshStandardNodeMaterial();
  shadowMat.colorNode = color('#000000');
  shadowMat.opacity = 0.35;
  shadowMat.transparent = true;
  const shadowMesh = new Mesh(shadowGeom, shadowMat);
  shadowMesh.rotation.x = -Math.PI / 2;
  shadowMesh.position.z = -0.08;
  root.add(shadowMesh);

  // Caption text (below button)
  const captionConfig = {
    fontSize: 9,
    color: '#e8ecf2',
    align: 'center',
    maxWidthPx: width * 100, // rough approximation
    letterSpacingPx: 0.12 * 9,
  };
  const captionText = ctx.fontAtlas.createText('NO DEPOSIT REQUIRED', captionConfig);
  captionText.position.set(0, - (height / 2 + 0.25), 0.01);
  captionText.rotation.x = -Math.PI / 2;
  root.add(captionText);

  // CTA label (centered on button)
  const labelConfig = {
    fontSize: 20,
    color: '#e8ecf2',
    align: 'center',
    maxWidthPx: (width - 0.5) * 100,
    letterSpacingPx: 0.08 * 20,
  };
  const labelText = ctx.fontAtlas.createText('BEGIN COMMISSION', labelConfig);
  labelText.position.set(0, 0, 0.01);
  labelText.rotation.x = -Math.PI / 2;
  root.add(labelText);

  // Timelines and animations
  const cleanupList = [];

  // Weighted-settle scale on mount
  const settleTL = gsap.timeline({
    defaults: { duration: 0.9, ease: 'cubic-bezier(0.165,0.84,0.44,1)' },
  });
  settleTL.fromTo(
    root.scale,
    { x: 1.04, y: 1.04, z: 1.04 },
    { x: 1, y: 1, z: 1 }
  );
  cleanupList.push(() => settleTL.kill());

  // Hover animation (enter/leave)
  const hoverEnterTL = gsap.timeline({ paused: true });
  hoverEnterTL.to(
    root.position,
    { z: 0.06, duration: 0.18, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' }
  );
  hoverEnterTL.to(
    edgeIntensity,
    { value: 2.2, duration: 0.18, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' },
    0
  );
  const hoverLeaveTL = gsap.timeline({ paused: true });
  hoverLeaveTL.to(
    root.position,
    { z: 0, duration: 0.18, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' }
  );
  hoverLeaveTL.to(
    edgeIntensity,
    { value: 1.6, duration: 0.18, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' },
    0
  );
  cleanupList.push(() => {
    hoverEnterTL.kill();
    hoverLeaveTL.kill();
  });

  // Press animation
  const pressTL = gsap.timeline({ paused: true });
  pressTL.to(root.scale, {
    x: 0.97,
    y: 0.97,
    z: 0.97,
    duration: 0.12,
    ease: 'cubic-bezier(0.175,0.885,0.32,1.275)',
  });
  cleanupList.push(() => pressTL.kill());

  // Handlers attachment
  root.userData.handlers = {
    hoverEnter: () => {
      hoverLeaveTL.pause(0);
      hoverEnterTL.restart();
    },
    hoverLeave: () => {
      hoverEnterTL.pause(0);
      hoverLeaveTL.restart();
    },
    pressDown: () => {
      pressTL.restart();
    },
    pressUp: () => {
      // Return to settled scale
      gsap.to(root.scale, {
        x: 1,
        y: 1,
        z: 1,
        duration: 0.12,
        ease: 'cubic-bezier(0.175,0.885,0.32,1.275)',
      });
    },
  };

  // Cleanup
  root.userData.cleanup = () => {
    cleanupList.forEach((fn) => fn());
    buttonGeom.dispose();
    shadowGeom.dispose();
    buttonMat.dispose();
    shadowMat.dispose();
    // Text objects may hold resources; assume they clean themselves on dispose
    if (labelText.dispose) labelText.dispose();
    if (captionText.dispose) captionText.dispose();
  };

  return root;
}
